{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service = 'invoice-agent'",
      "why": "Check if invoice-agent is also experiencing disk quota exhaustion, as it is used by worker and could be contributing to invoice extraction failures."
    }
  ],
  "hypotheses": [
    {
      "service": "sync-job",
      "kind": "resource_exhaustion",
      "mechanism": "Sync-job service exhausted its disk quota (998/1000 MB), causing ledger export write failures and sync errors.",
      "supporting": ["E3", "E6", "E15", "E28"],
      "refuting": [],
      "explains": ["E3", "E6"],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "sync-job"
          }
        }
      ]
    },
    {
      "service": "worker",
      "kind": "runtime_fault",
      "mechanism": "Worker service is stuck in a bad state causing repeated invoice file write failures despite having sufficient disk quota (60/1000 MB).",
      "supporting": ["E13", "E14", "E2", "E4", "E7", "E9"],
      "refuting": ["E28"],
      "explains": ["M2_error_burst", "M3_dead_letters"],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "worker"
          }
        }
      ]
    }
  ],
  "summary": "Sync-job has disk quota exhaustion, while worker is in a faulty state causing write failures despite available disk space."
}
